import { MeshBasicNodeMaterial } from 'three/webgpu';
import { mix, smoothstep, texture, uv, vec3 } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;
  const root = new Group();
  root.name = 'collection-card-2-label';

  const ownedGeometries = new Set();
  const ownedMaterials = new Set();
  const loadedTextures = new Set();
  const primitiveResults = [];
  let disposed = false;

  const makeMaterial = (options = {}) => {
    const material = new MeshBasicNodeMaterial(options);
    ownedMaterials.add(material);
    return material;
  };

  const makePlane = (width, height, material, z = 0) => {
    const geometry = new PlaneGeometry(width, height);
    ownedGeometries.add(geometry);
    const mesh = new Mesh(geometry, material);
    mesh.position.z = z;
    return mesh;
  };

  const stageGradient = mix(
    vec3(0.043, 0.043, 0.063),
    vec3(0.086, 0.086, 0.114),
    smoothstep(0.0, 1.0, uv().y)
  );

  const stageMaterial = makeMaterial({
    colorNode: stageGradient
  });
  const stage = makePlane(7.0, 6.0, stageMaterial, -2.5);
  stage.name = 'engineered-gradient-stage';
  root.add(stage);

  const shadowMaterial = makeMaterial({
    color: '#0b0b10',
    transparent: true,
    opacity: 0.48,
    depthWrite: false
  });
  const shadow = makePlane(3.1, 0.42, shadowMaterial, -0.12);
  shadow.name = 'contact-shadow';
  shadow.scale.y = 0.55;
  root.add(shadow);

  const cardGradient = mix(
    vec3(0.043, 0.043, 0.063),
    vec3(0.086, 0.086, 0.114),
    smoothstep(0.0, 1.0, uv().y)
  );

  const cardMaterial = makeMaterial({
    colorNode: cardGradient
  });
  const card = makePlane(3.15, 1.95, cardMaterial, 0);
  card.name = 'brushed-metal-card';
  root.add(card);

  const borderMaterial = makeMaterial({
    color: '#16161d',
    transparent: true,
    opacity: 0.9
  });
  const border = makePlane(3.02, 1.82, borderMaterial, 0.012);
  border.name = 'card-inner-border';
  root.add(border);

  const accentMaterial = makeMaterial({
    color: '#ff2a38'
  });
  const accent = makePlane(0.075, 1.22, accentMaterial, 0.03);
  accent.name = 'signal-red-accent';
  accent.position.set(-1.27, 0, 0);
  root.add(accent);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    if (typeof item?.text !== 'string') continue;

    const textObject = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 39,
      color: '#e8ecf2',
      align: 'left'
    });

    textObject.name = item.role === 'headline'
      ? 'collection-card-2-headline'
      : 'collection-card-2-text';

    textObject.position.set(-1.05, -0.03, 0.055);
    root.add(textObject);
  }

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((loadedTexture) => {
      if (disposed) {
        loadedTexture.dispose?.();
        return;
      }

      loadedTextures.add(loadedTexture);
      loadedTexture.wrapS = ctx.THREE.ClampToEdgeWrapping;
      loadedTexture.wrapT = ctx.THREE.ClampToEdgeWrapping;
      cardMaterial.colorNode = texture(loadedTexture).mul(cardGradient);
      cardMaterial.needsUpdate = true;
    });
  }

  for (const primitive of config.cinematicPrimitives ?? []) {
    const handler = ctx.primitives?.[primitive.name];
    if (typeof handler === 'function') {
      const result = handler(root, primitive.params);
      if (result) primitiveResults.push(result);
    }
  }

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const result of primitiveResults) {
      result?.cleanup?.();
      result?.timeline?.kill?.();
    }

    for (const textureResource of loadedTextures) {
      textureResource.dispose?.();
    }

    for (const geometry of ownedGeometries) {
      geometry.dispose?.();
    }

    for (const material of ownedMaterials) {
      material.dispose?.();
    }

    root.clear();
  };

  return root;
}
